@Composable
fun Tracker(owner: LifecycleOwner, onStart: () -> Unit) {
    val current by rememberUpdatedState(onStart)
    DisposableEffect(owner) {
        val obs = LifecycleEventObserver { _, e ->
            if (e == Lifecycle.Event.ON_START) current()
        }
        owner.lifecycle.addObserver(obs)
        onDispose { owner.lifecycle.removeObserver(obs) }
    }
}

